void shellSort(int a[], int n) {
    for(int gap=n/2;gap>0;gap/=2)
        for(int i=gap;i<n;i++){int t=a[i],j=i;
            while(j>=gap&&a[j-gap]>t){a[j]=a[j-gap];j-=gap;}a[j]=t;}
}
